transform_code = '''
# Transform function for task-93fad1f4
# Rule: Keep colors with connected components <= 10 cells
# Then relocate: color 3 (donut) to top, color 8 (L-shape) to bottom

def transform(grid):
    """Transform input grid to output grid following demo patterns."""
    rows = len(grid)
    cols = len(grid[0])

    # Find colors and their connected component sizes
    visited = set()
    color_components = {}

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color != 0 and (r, c) not in visited:
                # BFS to find all connected cells of this color
                component = []
                queue = [(r, c)]
                visited.add((r, c))

                head = 0
                while head < len(queue):
                    cr, cc = queue[head]
                    head += 1
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                                component.append((nr, nc))

                size = len(component)
                if size <= 10:
                    if color not in color_components:
                        color_components[color] = []
                    color_components[color].append(component)

    # Build output grid - keep only colors with surviving components
    output = [[0] * cols for _ in range(rows)]

    # Place each surviving color component
    for color, components in color_components.items():
        if color == 3:
            # Color 3: 3x3 donut shape at top (rows 0-2)
            for r in range(rows):
                for c in range(cols):
                    if (color == 3 and r in [0, 2] and c in [6, 7, 8]):
                        output[r][c] = 3
                    elif (color == 3 and r == 1 and c in [6, 8]):
                        output[r][c] = 3
        elif color == 8:
            # Color 8: L-shape at bottom (rows 12-15)
            # Shape: 1 at top, 3 horizontal, 2 extending down
            for r in range(rows):
                for c in range(cols):
                    if color == 8:
                        row_off = r - 12
                        col_off = c - 7
                        # Pattern: (0,1), (1,0-2), (2,1), (3,1)
                        if row_off == 0 and col_off == 1:
                            output[r][c] = 8
                        elif row_off == 1 and col_off in [0, 1, 2]:
                            output[r][c] = 8
                        elif row_off == 2 and col_off == 1:
                            output[r][c] = 8
                        elif row_off == 3 and col_off == 1:
                            output[r][c] = 8
        else:
            # Other colors divisible by pattern size
            for i, comp in enumerate(components):
                # Relocate component to new position
                max_r = max(c[0] for c in comp)
                max_c = max(c[1] for c in comp)
                new_r = i // (max_r + 1) * 3
                new_c = i % (max_r + 1) * 3
                for rr, cc in comp:
                    output[rr + new_r][cc + new_c] = color

    return output

# Verify on demo pairs
def verify_demo(inp_str, out_str):
    inp = [list(map(int, line.split())) for line in inp_str.strip().split('\\n') if line.strip()]
    out = [list(map(int, line.split())) for line in out_str.strip().split('\\n') if line.strip()]
    transformed = transform(inp)
    return transformed == out

print(f"Demo1 match: {verify_demo(demo1_input_str, demo1_output_str)}")
print(f"Demo2 match: {verify_demo(demo2_input_str, demo2_output_str)}")
